{
  "findings": [
    {
      "check_id": "CKV_AWS_364",
      "title": "Lambda permission lacks SourceArn or SourceAccount restriction",
      "resource": "aws_lambda_permission.api_gateway_invoke",
      "severity": "MEDIUM",
      "explanation": "The Lambda permission allows any API Gateway instance to invoke the function because it does not specify source_arn or source_account. This creates a risk of unauthorized invocation if an attacker sets up their own API Gateway endpoint."
    }
  ],
  "patched_code": "resource \"aws_lambda_permission\" \"api_gateway_invoke\" {\n  statement_id  = \"AllowExecutionFromAPIGateway\"\n  action        = \"lambda:InvokeFunction\"\n  function_name = aws_lambda_function.log_processing_pipeline.function_name\n  principal     = \"apigateway.amazonaws.com\"\n  source_arn    = \"${aws_apigatewayv2_api.main.execution_arn}/*/*\"\n}",
  "fix_summary": "Added the `source_arn` argument to restrict the Lambda permission so that only invocations originating from the specific API Gateway execution ARN are allowed, mitigating the risk of unauthorized access."
}
